def sum_odd_length_subarrays(arr):
    n = len(arr)
    total = 0
    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += arr[end]                                # extend the subarray by one element
            length = end - start + 1
            if length % 2 == 1:
                total += current_sum                                    # only odd-length subarrays contribute
    return total


if __name__ == "__main__":
    print(sum_odd_length_subarrays([1, 4, 2, 5, 3]))

