import java.util.*;

public class Main {
    int sumOddLengthSubarrays(int[] arr) {
        int n = arr.length;
        int total = 0;
        for (int start = 0; start < n; start++) {
            int currentSum = 0;
            for (int end = start; end < n; end++) {
                currentSum += arr[end];                                    // extend the subarray by one element
                int length = end - start + 1;
                if (length % 2 == 1) {
                    total += currentSum;                                        // only odd-length subarrays contribute
                }
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.sumOddLengthSubarrays(new int[]{1, 4, 2, 5, 3}));
    }
}

