import java.util.*;

public class Main {
    int sumOddLengthSubarrays(int[] arr) {
        int n = arr.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            int left = i + 1;                                              // choices for where the subarray could start
            int right = n - i;                                                // choices for where the subarray could end
            int oddLeft = (left + 1) / 2;                                        // of those starts, how many keep the total length odd
            int evenLeft = left / 2;
            int oddRight = (right + 1) / 2;
            int evenRight = right / 2;
            int count = oddLeft * oddRight + evenLeft * evenRight;                 // total odd-length subarrays containing index i
            total += arr[i] * count;                                                 // this element's full contribution
        }
        return total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.sumOddLengthSubarrays(new int[]{1, 4, 2, 5, 3}));
    }
}

